<script setup lang="ts">
import {ref} from 'vue';import {useRouter} from 'vue-router';import {api,errorText,session} from '../lib/api';import Icon from '../components/Icon.vue';import Notice from '../components/Notice.vue'
const router=useRouter(),current=ref(''),password=ref(''),repeat=ref(''),busy=ref(false),error=ref('')
async function change(){error.value='';if(password.value!==repeat.value){error.value='两次输入的新密码不一致。';return}busy.value=true;try{await api('/api/auth/password',{method:'POST',body:{current_password:current.value,new_password:password.value}});current.value=password.value=repeat.value='';Object.assign(session,{authenticated:false,csrf:'',checked:false});await router.replace({path:'/admin/login',query:{changed:'1'}})}catch(e){error.value=errorText(e)}finally{busy.value=false}}
</script><template><div class="admin-heading"><div><span class="eyebrow">ACCOUNT SECURITY</span><h1>账户安全</h1><p>管理控制台登录凭据。</p></div></div><Notice :message="error"/><section class="card settings-section"><div class="card-heading"><h2>当前账户</h2></div><dl class="detail-list"><div><dt>用户名</dt><dd>{{session.username}}</dd></div><div><dt>身份</dt><dd>管理员</dd></div><div><dt>会话保护</dt><dd>HttpOnly Cookie · CSRF 校验</dd></div></dl></section><form class="card settings-section" @submit.prevent="change"><div class="card-heading"><h2>修改密码</h2><p class="muted">修改后会注销现有会话，请使用新密码重新登录。</p></div><div class="form-grid"><label class="field full">当前密码<input v-model="current" type="password" autocomplete="current-password" required maxlength="256"></label><label class="field">新密码<input v-model="password" aria-label="新密码" type="password" autocomplete="new-password" required minlength="8" maxlength="256"><span class="help">至少 8 个字符，避免与其他服务共用。</span></label><label class="field">再次输入新密码<input v-model="repeat" type="password" autocomplete="new-password" required minlength="8" maxlength="256"></label></div><button class="btn primary" :disabled="busy"><Icon name="lock" :size="17"/>{{busy?'更新中…':'更新密码'}}</button></form></template>
